<?php
 namespace Pterodactyl\Http\Controllers\Dezerx; use Illuminate\Http\Response; use Pterodactyl\Services\Dezerx\Seo; use Pterodactyl\Services\Dezerx\OgImage; use Pterodactyl\Http\Controllers\Controller; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class OgImageController extends Controller { public function __invoke(string $stamp, string $slug): Response { if (preg_match('/^[a-z0-9]{6,32}$/', $stamp) !== 1) { throw new NotFoundHttpException(); } if (preg_match('/^[a-z0-9-]{1,32}$/', $slug) !== 1 || !Seo::knows($slug)) { throw new NotFoundHttpException(); } $bytes = OgImage::render($slug); if ($bytes === null) { throw new NotFoundHttpException(); } $this->cache($stamp, $slug, $bytes); return new Response($bytes, 200, [ 'Content-Type' => 'image/png', 'Cache-Control' => 'public, max-age=31536000, immutable', ]); } private function cache(string $stamp, string $slug, string $bytes): void { if ($stamp !== OgImage::stamp()) { return; } $root = public_path('dezerx/og'); $directory = $root . '/' . $stamp; if (!is_dir($directory) && !@mkdir($directory, 0o755, true) && !is_dir($directory)) { return; } @file_put_contents($directory . '/' . $slug . '.png', $bytes); $this->prune($root, $stamp); } private function prune(string $root, string $keep): void { foreach (glob($root . '/*', GLOB_ONLYDIR) ?: [] as $path) { if (basename($path) === $keep) { continue; } foreach (glob($path . '/*.png') ?: [] as $file) { @unlink($file); } @rmdir($path); } } } 